import { Kernel } from './kernel.ts';
import { DeterministicRng } from './rng.ts';

export const KERNEL_SEED = 0xc0ffee;
export const TRACE_PACKETS = 50;
export const TRACE_TIMEOUTS = 3;
export const TRACE_RESEEDS = 2;

/**
 * Build the acceptance-test trace: 50 network packet arrivals, 3 clock
 * interrupt timeouts and 2 random-seed injections (55 events total).
 * The trace layout itself is generated by a separate driver RNG so the
 * scenario is identical on every machine and every run.
 */
export function buildScenario(): Kernel {
  const kernel = new Kernel(KERNEL_SEED);
  const driver = new DeterministicRng(0x5eed);

  let tick = 1;
  for (let i = 1; i <= TRACE_PACKETS; i += 1) {
    tick += 1 + driver.nextInt(4);
    kernel.inject({
      kind: 'packet',
      tick,
      payload: {
        id: i,
        from: `host-${driver.nextInt(6)}`,
        size: 64 + driver.nextInt(1409),
      },
    });
  }

  const timeoutTicks = [20, 75, 140];
  for (let i = 0; i < TRACE_TIMEOUTS; i += 1) {
    kernel.inject({
      kind: 'timeout',
      tick: timeoutTicks[i],
      payload: { timerId: `retrans-${i}` },
    });
  }

  const reseeds: Array<{ tick: number; seed: number; reason: string }> = [
    { tick: 40, seed: 0xabcd, reason: 'epoch-rotation' },
    { tick: 110, seed: 0x1234, reason: 'epoch-rotation' },
  ];
  for (const r of reseeds) {
    kernel.inject({ kind: 'reseed', tick: r.tick, payload: { seed: r.seed, reason: r.reason } });
  }

  kernel.run();
  return kernel;
}
